import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputValues = scanner.nextLine().split(" ");
        int[] values = new int[inputValues.length];
        for (int i = 0; i < inputValues.length; i++) {
            values[i] = Integer.parseInt(inputValues[i]);
        }
        Arrays.sort(values);

        if (values[0] == 1) {
            int quotient = values[1] / 6;
            int remainder = values[1] % 6;
            int base_value = quotient * 6;
            if (remainder <= 3) {
                System.out.println(base_value);
            } else if (remainder == 4) {
                System.out.println(base_value + 2);
            } else if (remainder == 5) {
                System.out.println(base_value + 4);
            }
        } else if (values[0] == 2) {
            if (values[1] == 2) {
                System.out.println(0);
            } else if (values[1] == 3) {
                System.out.println(4);
            } else if (values[1] == 7) {
                System.out.println(12);
            } else {
                System.out.println(values[1] * 2);
            }
        } else if (values[0] == 3) {
            if (values[1] == 3) {
                System.out.println(8);
            } else if (values[1] >= 4) {
                System.out.println((values[0] * values[1]) / 2 * 2);
            }
        } else {
            System.out.println((values[0] * values[1]) / 2 * 2);
        }
        scanner.close();
    }
}
